import time
import enum
import os
from ta_emss.utilities.trs.jsonrpc import ErrRpcTimeout
from ta_emss.utilities.trs.registry import rpc_client


RunState = enum.Enum('RunState', {"init": -1, "prepared": 1, "running": 2, "terminating": 3, "stopped": 0})
Status = enum.Enum('Status', {"TIMEOUT": -1, "SUCCESS": 1, "FAILURE": 0})
TIMEOUT = Status.TIMEOUT
SUCCESS = Status.SUCCESS
FAILURE = Status.FAILURE

MINIMUM_TIMEOUT = 0.1


class ErrDataHandler(Exception):
    '''Base class for exceptions related to DataHandlers'''
    pass


class ErrAlreadyRuning(ErrDataHandler):
    def __init__(self, err_data):
        super(ErrAlreadyRuning, self).__init__(str(err_data))
        self.err = err_data


class ErrInfiniteLoop(ErrDataHandler):
    def __init__(self, err_data):
        super(ErrInfiniteLoop, self).__init__(str(err_data))
        self.err = err_data


class DataHandler(object):
    '''Base class for all handlers processing data'''

    def __init__(self, method=None, timeout=10, rpc_connection_name='localRPC'):
        super(DataHandler, self).__init__()
        self.method = method
        self.timeout = timeout
        self.status = None
        self._run_state = RunState.init
        self._ret = None
        self._start_time = 0
        self._end_time = 0
        self._data_cb_name = None
        self._timeout_cb_name = None
        self._silent = False
        self.rpc = rpc_client(rpc_connection_name)
        if (timeout is not None) and (timeout <= MINIMUM_TIMEOUT):
            self.timeout = MINIMUM_TIMEOUT  # request to expire it immediately --> give it time to run before it expires

    def run(self, *run_params, **run_kwparams):
        '''Run data-handler in foreground, start & await till finished'''
        self._set_silent_from_env()
        started = self.start(*run_params, **run_kwparams)
        if started:
            if 'timeout' in run_kwparams:
                self.await_finish(timeout=run_kwparams['timeout'])
            else:
                self.await_finish()
        return self.status == Status.SUCCESS

    def run_silently(self, *run_params, **run_kwparams):
        '''Run data-handler in foreground silently, start & await till finished'''
        self._silent = True
        self._set_silent_from_env()
        return self.run(*run_params, **run_kwparams)

    def _set_silent_from_env(self):
        try:
            if 'SILENT_OM' in os.environ:
                self._silent = int(os.environ['SILENT_OM'])
        except Exception:
            pass

    def start(self, *run_params, **run_kwparams):
        '''Start running data-handler in background'''
        try:
            return self._start(*run_params, **run_kwparams)
        except ErrRpcTimeout:
            print("[HANDLER]: ErrRpcTimeout")
            self._on_timeout()
            return False

    def _start(self, *run_params, **run_kwparams):
        if self.is_running():  # next run may be run request with different run parameters
            msg = "Can't start %s - it is already running" % self
            raise ErrAlreadyRuning(msg)

        self.status = None
        self._ret = None
        self.on_prepare_run(*run_params, **run_kwparams)  # derived may set status even here
        if self.is_completed():
            self._finalize_run()
        else:
            self._run_state = RunState.prepared
            self.on_start_run(*run_params, **run_kwparams)  # derived may set status even here
            if self.is_completed():
                self._finalize_run()
            else:
                self._run_state = RunState.running

        return self.is_running()

    def on_prepare_run(self, *run_params, **run_kwparams):
        '''Preparation for running data-handler'''
        self.status = None
        self._ret = None
        self._start_time = self._end_time = time.time()
        assert ((self.timeout is None) or (self.timeout > 0))
        if self.method is None:
            self.status = Status.FAILURE
            return
        try:
            timeout = run_kwparams["timeout"]
        except KeyError:
            timeout = None
        if timeout is None:
            timeout = self.timeout
        self._data_cb_name = self.rpc.register_method(fun=self._on_new_data)
        self._timeout_cb_name = self.rpc.start_timer(timeout=timeout, timeout_action=self._on_timeout)

    def on_start_run(self, *run_params, **run_kwparams):
        '''RPC call'''
        if run_kwparams:
            timeout = run_kwparams.pop('timeout', self.timeout)
            result = self.rpc.call(method=self.method,
                                   notification=False,
                                   timeout=timeout,
                                   silent=self._silent,
                                   on_data_callback=self._data_cb_name,
                                   command_params=run_kwparams)
        else:
            result = self.rpc.call(method=self.method,
                                   notification=False,
                                   timeout=self.timeout,
                                   silent=self._silent,
                                   on_data_callback=self._data_cb_name,
                                   command_params=run_params)
        if result:
            self._run_state = RunState.running
            if result['status'] == 'error':
                self.status = Status.FAILURE
                self.failure_reason = result['msg']
            elif result['status'] == 'stopped':
                self.status = Status.SUCCESS
        else:
            self.status = Status.FAILURE

    def await_finish(self, timeout=None):
        '''Await till data-handler is finished'''
        if not self.is_running():
            return True

        forced_end_of_run_time = None
        if timeout is not None:
            self.set_timeout(timeout)
            forced_end_of_run_time = time.time() + timeout

        if self.timeout is None:
            self.stop()
            msg = "Infinite loop requested via await_finish(): can't use timeout=None in foreground"
            raise ErrInfiniteLoop(msg)

        while not self.is_completed():
            now = time.time()
            if timeout is None:
                expected_end_of_run_time = self._start_time + self.timeout
                if now > (expected_end_of_run_time + 1.0):
                    self.stop()
                    msg = "Infinite await_finish(): %s has not completed even after %s [sec], timeout=%s" % (self.__class__.__name__, now - self._start_time, self.timeout)
                    raise ErrInfiniteLoop(msg)
            else:
                forced_end_of_run_time = self._start_time + timeout
                if now > (forced_end_of_run_time + 0.2):
                    self.status = Status.TIMEOUT
                    self._run_state = RunState.terminating
                    self._end_time = time.time()
                    self.stop()
                    self._run_state = RunState.stopped
                    return True

            time.sleep(0.01)
        self.stop()
        return True

    def on_new_data(self, **data):
        '''Derived classes should overwrite this method to perform real handling'''
        pass

    def _on_new_data(self, **data):
        '''Full handling of data-handler's incomming data'''
        if not self.is_completed():
            self.on_new_data(**data)

    def set_timeout(self, timeout):
        '''Change timeout of running DataHandler'''
        self.rpc.stop_timer(timeout_action=self._on_timeout, name=self._timeout_cb_name)
        if self.is_running() and (timeout is not None):
            if timeout < 0:
                timeout = 0  # means: expire timer now!
            now = time.time()
            already_elapsed = now - self._start_time
            self.timeout = already_elapsed + timeout
        self._timeout_cb_name = self.rpc.start_timer(timeout=self.timeout, timeout_action=self._on_timeout)

    def on_timeout(self):
        '''Actions executed when timeout'''
        self.status = Status.TIMEOUT

    def _on_timeout(self):
        if not self.is_completed():
            self.on_timeout()
        if self.is_completed() and self.is_running() and self._run_state != 'terminating':
            self._finalize_run()

    def _finalize_run(self):
        old_run_state = self._run_state
        self._run_state = RunState.terminating
        self._end_time = time.time()
        if self.is_completed():
            self.stop()
            self._run_state = RunState.stopped
        else:
            self._run_state = old_run_state

    def stop(self):
        '''Stop running data-handler'''
        self.rpc.stop_timer(timeout_action=self._on_timeout, name=self._timeout_cb_name)
        self.rpc.unregister_method(fun=self._on_new_data, name=self._data_cb_name)

        if self.is_running():
            self._run_state = RunState.stopped
        return True

    def is_completed(self):
        '''Check if finished'''
        if self.status is None:
            return False
        return self.status in Status

    def is_running(self):
        '''Check if running'''
        return (self._run_state != RunState.init) and (self._run_state != RunState.stopped)

    def get_status(self):  # None  Status.TIMEOUT  Status.SUCCESS  Status.FAILURE
        '''Get status'''
        return self.status

    def returned_data(self):
        '''Return result produced by data-handler'''
        return self._ret
